def health(service):
    if service not in ("checkout", "inventory"):
        raise ValueError("unknown service")
    return {"service": service, "status": "healthy"}

async def agent_events():
    for text in ("Synthetic step", "Synthetic answer"):
        yield {"event":"message", "text":text}

def interactive_events():
    value = yield "ready"
    while True:
        value = yield use_source_value(value)

